import{_t as e,it as t,n,rt as r}from"./chunks/framework.C5Z6qjff.js";var i=JSON.parse(`{"title":"Entities – Write","description":"","frontmatter":{"title":"Entities – Write"},"headers":[],"relativePath":"de/api/reference/entities-write.md","filePath":"de/api/reference/entities-write.md"}`),a={name:`de/api/reference/entities-write.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="entities-–-write" tabindex="-1">Entities – Write <a class="header-anchor" href="#entities-–-write" aria-label="Permalink to “Entities – Write”">​</a></h1><div><p>Operationen des Tags <strong>Entities – Write</strong>, die dieses Release implementiert. Erzeugt aus <code>api/openapi.yaml</code>; geplante Operationen sind nicht aufgeführt. Die Beschreibungen stammen aus dem englischen API-Vertrag.</p><h2 id="batchWriteEntities" tabindex="-1">Create/update entities and connections in batch <a class="header-anchor" href="#batchWriteEntities" aria-label="Permalink to “Create/update entities and connections in batch”">​</a></h2><p><code>POST /entities/batch</code> · <code>batchWriteEntities</code></p><p>Writes up to 500 entities and 500 connections in one request. The preferred endpoint for external systems with <code>strategy: upsert</code> (ADR-026). <code>?dryRun=true</code> → validation without persisting. Not supported yet: connections (US-141 AC2) and <code>dryRun=true</code> (US-141 AC3) are rejected with 422; <code>parentId</code> and <code>lifecycle</code> are item errors. <code>X-Agent-Id</code> is stored only as the informational audit field <code>agent_label</code> (ADR-033 §7).</p><p><strong>Zugriff</strong>: Berechtigung <code>entity:write</code>; zusätzlich <code>visibility-scope:assign</code>, wenn: a connection of a type used as scopingConnectionType is written</p><h3 id="parameter" tabindex="-1">Parameter <a class="header-anchor" href="#parameter" aria-label="Permalink to “Parameter”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Ort</th><th>Pflicht</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>dryRun</code></td><td>query</td><td>nein</td><td>boolean</td><td>–</td></tr><tr><td><code>X-Agent-Id</code></td><td>header</td><td>nein</td><td>string</td><td>Informational label of the calling tool (ADR-026, ADR-033 §7). Stored untrusted as <code>agentLabel</code>; never used for attribution, filtering or authorization. Longer values are truncated to 100 characters; control characters are removed.</td></tr><tr><td><code>X-Agent-Run</code></td><td>header</td><td>nein</td><td>string</td><td>Informational correlation ID of a run of the calling tool (stored as <code>agentRun</code>)</td></tr></tbody></table><h3 id="request-body" tabindex="-1">Request-Body <a class="header-anchor" href="#request-body" aria-label="Permalink to “Request-Body”">​</a></h3><ul><li><code>application/json</code>: BatchWriteRequest</li></ul><h3 id="antworten" tabindex="-1">Antworten <a class="header-anchor" href="#antworten" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>200</td><td>Batch result (also for partial errors if atomic=false)</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code> and <code>POST /me/password/suggestion</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code></td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>422</td><td>Entire batch invalid, nothing written: more entities than the limit, connections or dryRun=true (not supported yet), or atomic=true with at least one faulty item (<code>errors[].field</code> carries the item index, e.g. <code>entities[3].properties</code>).</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};